package ru.transferservis.admin.data;
import com.google.gson.*;
import java.io.IOException;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class VehicleAssessmentTest {
    static JsonObject json(String s){return JsonParser.parseString(s).getAsJsonObject();}
    static AdminAccess owner(){return AdminAccess.fromResponse(json("{\"ok\":true,\"admin\":{\"accountId\":\"staff_operator001\",\"role\":\"owner\",\"permissions\":[\"*\"],\"mfa\":{\"required\":true,\"verified\":true,\"method\":\"totp\",\"expiresAt\":9007199254740991}}}"),"staff_operator001");}
    static VehicleAssessment.Parameters params(String model,String year)throws IOException{return new VehicleAssessment.Parameters("Toyota",model,year,"hybrid","sedan");}
    static VehicleAssessment.Context context(JsonObject metadata)throws Exception {
        JsonObject b=ModerationTestData.body(),r=b.getAsJsonObject("registration");r.getAsJsonArray("vehicles").add(json("{\"id\":\""+VehicleClassificationTest.CAR+"\",\"make\":\"Toyota\",\"model\":\"Camry\",\"plate\":\"SYNTH-01\",\"revision\":4}"));r.getAsJsonArray("documents").remove(0);
        for(String side:new String[]{"front","back"})r.getAsJsonArray("documents").add(json("{\"id\":\"document_"+side+"001\",\"vehicleId\":\""+VehicleClassificationTest.CAR+"\",\"kind\":\"sts_"+side+"\",\"status\":\"verified\",\"revision\":1}"));
        return new VehicleAssessment.Context(owner(),1,RegistrationReview.parse(b,"staff_driver123"),VehicleClassificationTest.CAR,VehicleClassification.Page.parse(metadata,VehicleClassificationTest.CAR,"",null));
    }
    static VehicleClassification.Rule rule()throws Exception{return VehicleClassification.Rule.parse(json("{\"ok\":true,\"requestId\":\"req_fixture001\",\"rule\":{\"version\":\"rule_basis001\",\"make\":\"Toyota\",\"model\":\"Camry\",\"revision\":1,\"minYear\":2023,\"vehicleClass\":\"comfort\",\"allowedBodyTypes\":[\"sedan\"],\"conditions\":[{\"id\":\"rule_basis001:1\",\"text\":\"Synthetic condition\"}]}}"),"rule_basis001");}
    static VehicleAssessment.Selection selection(VehicleAssessment.Context c,boolean exception)throws Exception {VehicleClassification.Rule r=rule();return new VehicleAssessment.Selection(c,params("Camry","2023"),exception,c.page.pinnedRuleVersion,r,exception?"Camry":"",r.conditions);}
    static VehicleAssessmentAction action(VehicleAssessment.Selection s,List<String> results,Set<String> waivers,boolean year)throws Exception {return VehicleAssessmentAction.create(owner(),s,s.parameters,s.exception,s.basisModel,s.context.documents.get(0),s.context.documents.get(1),results,waivers,year,"Synthetic reason");}
    private interface Invalid{void run()throws Exception;}private void rejects(Invalid f)throws Exception{try{f.run();fail("Invalid review accepted");}catch(IOException expected){}}
    @Test public void payloadIsImmutableAndHasNoClassOrClientTrustFlags()throws Exception {VehicleAssessmentAction a=action(selection(context(VehicleClassificationTest.metadata()),false),List.of(""),Set.of(),false);assertEquals(9,a.body().size());assertEquals(5,a.body().getAsJsonObject("parameters").size());assertFalse(a.body().has("vehicleClass"));assertTrue(a.body().getAsJsonArray("conditions").isEmpty());String original=a.body().toString();a.body().addProperty("approved",true);assertEquals(original,a.body().toString());assertTrue(a.key.startsWith("vehicle-review-"));}
    @Test public void exceptionRetainsTargetPinAndSeparateBasisVersion()throws Exception {VehicleAssessmentAction a=action(selection(context(VehicleClassificationTest.metadata()),true),List.of("unmet"),Set.of("rule_basis001:1"),true);assertEquals("rule_fixture001",a.body().get("expectedRuleVersion").getAsString());assertEquals("rule_basis001",a.body().getAsJsonObject("exception").get("basisRuleVersion").getAsString());assertTrue(a.body().getAsJsonObject("exception").get("yearBelowMinimum").getAsBoolean());}
    @Test public void dispatcherCannotUseExceptionEvenWithErroneousGrants()throws Exception {VehicleAssessment.Selection s=selection(context(VehicleClassificationTest.metadata()),true);AdminAccess dispatcher=AssignmentTestData.access("vehicles.verify","vehicles.approve_exception","vehicle_rules.manage");assertFalse(dispatcher.canApproveVehicleException());rejects(()->VehicleAssessmentAction.create(dispatcher,s,s.parameters,true,"Camry",s.context.documents.get(0),s.context.documents.get(1),List.of("unmet"),Set.of(),false,"reason"));assertTrue(owner().canApproveVehicleException());}
    @Test public void changedParametersRequireExplicitRuleReload()throws Exception {VehicleAssessment.Selection s=selection(context(VehicleClassificationTest.metadata()),false);assertFalse(s.matches(params("Camry","2024"),false,""));assertFalse(s.matches(new VehicleAssessment.Parameters("Toyota","Camry","2023","combustion","sedan"),false,""));rejects(()->VehicleAssessmentAction.create(owner(),s,params("Camry","2024"),false,"",s.context.documents.get(0),s.context.documents.get(1),List.of(""),Set.of(),false,"reason"));}
    @Test public void waiverMustReferenceAnExplicitUnmetConditionInOwnerMode()throws Exception {VehicleAssessment.Selection x=selection(context(VehicleClassificationTest.metadata()),true),s=selection(x.context,false);rejects(()->action(x,List.of("satisfied"),Set.of("rule_basis001:1"),false));rejects(()->action(x,List.of("unmet"),Set.of("unknown"),false));rejects(()->action(s,List.of("unmet"),Set.of(),true));rejects(()->action(s,List.of(),Set.of(),false));}
    @Test public void missingEvidenceAndCrossContextDocumentsAreRejected()throws Exception {VehicleAssessment.Selection s=selection(context(VehicleClassificationTest.metadata()),false);VehicleAssessment.Document foreign=context(VehicleClassificationTest.metadata()).documents.get(0);rejects(()->VehicleAssessmentAction.create(owner(),s,s.parameters,false,"",foreign,s.context.documents.get(1),List.of(""),Set.of(),false,"reason"));rejects(()->VehicleAssessmentAction.create(owner(),s,s.parameters,false,"",null,s.context.documents.get(1),List.of(""),Set.of(),false,"reason"));}
    @Test public void formatDoesNotInventPowertrainBodyYearOrReason()throws Exception {for(String year:List.of("0","10000","2023.5","-1","202a"))rejects(()->params("Camry",year));rejects(()->new VehicleAssessment.Parameters("Toyota","Camry","2023","","sedan"));rejects(()->new VehicleAssessment.Parameters("Toyota","Camry","2023","hybrid",""));for(String reason:List.of(" ","\u00a0\uFEFF","line\nsecret","x".repeat(1001)))rejects(()->VehicleAssessment.text(reason,1000));assertEquals("Toyota",VehicleAssessment.text("\u00a0Toyota\uFEFF",80));}
    @Test public void unchangedLegacyUnboundInputCannotBeInvented()throws Exception {JsonObject b=VehicleClassificationTest.metadata();b.add("inputRevision",JsonNull.INSTANCE);b.add("pinnedRuleVersion",JsonNull.INSTANCE);VehicleAssessment.Selection s=selection(context(b),false);rejects(()->action(s,List.of(""),Set.of(),false));}
    static JsonObject ack(VehicleAssessmentAction a){JsonObject b=json("{\"ok\":true,\"requestId\":\"req_fixture001\",\"vehicleId\":\""+a.context.vehicleId+"\",\"vehicleRevision\":5,\"inputRevision\":1,\"requiresDispatcherReassignment\":true,\"classification\":{\"outcome\":\"candidate\",\"vehicleClass\":\"comfort\",\"ruleVersion\":\"rule_fixture001\",\"reasonCodes\":[]}}");return b;}
    @Test public void acknowledgementCannotCrossVehicleRevisionInputOrRule()throws Exception {VehicleAssessmentAction a=action(selection(context(VehicleClassificationTest.metadata()),false),List.of("satisfied"),Set.of(),false);assertTrue(a.validateAck(ack(a)).dispatcher);for(String field:List.of("vehicleRevision","inputRevision")){JsonObject b=ack(a);b.addProperty(field,100);rejects(()->a.validateAck(b));}JsonObject b=ack(a);b.addProperty("vehicleId","vehicle_foreign001");rejects(()->a.validateAck(b));JsonObject r=ack(a);r.getAsJsonObject("classification").addProperty("ruleVersion","rule_wrong001");rejects(()->a.validateAck(r));}
    @Test public void acknowledgementUnknownPrivateFieldsAndBooleanCoercionFailClosed()throws Exception {VehicleAssessmentAction a=action(selection(context(VehicleClassificationTest.metadata()),false),List.of("satisfied"),Set.of(),false);JsonObject b=ack(a);b.addProperty("privateObjectKey","PRIVATE");rejects(()->a.validateAck(b));JsonObject bool=ack(a);bool.addProperty("requiresDispatcherReassignment","true");rejects(()->a.validateAck(bool));}
    @Test public void keyChangesIncrementOnlyInputGeneration()throws Exception {VehicleAssessment.Context c=context(VehicleClassificationTest.metadata());VehicleAssessment.Parameters p=params("Camry","2024");VehicleAssessment.Selection s=new VehicleAssessment.Selection(c,p,false,"rule_current001",null,"",List.of());VehicleAssessmentAction a=action(s,List.of(),Set.of(),false);JsonObject b=ack(a);b.addProperty("inputRevision",2);b.getAsJsonObject("classification").addProperty("ruleVersion","rule_current001");assertEquals(2,a.validateAck(b).inputRevision);}
}
